// Get the 'results' array from the HTTP Request Node output

const results = $json.results;



// Extract the URLs from each result

const extractedUrls = results.map(result => ({

    url: result.url,

    title: result.title,

    // Optional: Include title if needed for context

    description: result.description,

    // Optional: Include description if needed

}));



// Return structured output

return extractedUrls;

// Get the input HTML from json.data

const html = $json.data || "";



if (!html) {

    throw new Error("No HTML content provided in json.data. Ensure the input contains valid HTML.");

}



// Function to extract and clean content from specified tags

function extractAndCleanContent(html, tag) {

    const regex = new RegExp(`<${tag}[^>]*>(.*?)<\/${tag}>`, "gis");

    const matches = [...html.matchAll(regex)];



    // Remove nested HTML tags and return plain text

    return matches.map(match => match[1].replace(/<[^>]*>/g, "").trim());

}



// Extract and clean body text (from <p> and <span> tags)

const bodyText = [

    ...extractAndCleanContent(html, "p"),

    ...extractAndCleanContent(html, "span")

];



// Return the clean text as an array

return {

    bodyText

};

